function audit=auditV4ExperimentAR14()
root=v4SetupPaths();base=fullfile(root,'results','formal','track_a','R14-dual-hypothesis');summary=readtable(fullfile(root,'results','reports','R14_EXPERIMENT_A_FORMAL_SUMMARY.csv'));ok=true;total=0;hashes=strings(20,1);
for ci=1:2,for si=1:10,index=(ci-1)*10+si;snr=-31+si;path=fullfile(base,sprintf('case_%d',ci),sprintf('snr_%+03d',snr),'formal_cell.mat');x=load(path,'formalCell');f=x.formalCell;s=f.state;rows=summary.caseIndex==ci&summary.snrDb==snr;paper=sum(double(s.symbolErrors(:,3)))/(20000*23);stage=sum(double(s.symbolErrors(:,4)))/(20000*23);ok=ok&&f.completedPackets==20000&&sum(rows)==1&&abs(summary.paperSer(rows)-paper)<1e-15&&abs(summary.stageSer(rows)-stage)<1e-15;total=total+f.completedPackets;hashes(index)=v4Sha256(path);end,end
source=v4VerifyReadOnlySources(root);acceptance=fullfile(root,'R14_USER_ACCEPTANCE.md');better=sum(summary.stageBetter);inconclusive=sum(summary.lower95<=0&summary.upper95>=0);passed=ok&&total==400000&&source.passed&&better==19&&inconclusive>=1&&isfile(acceptance);
audit=struct('report','EXPERIMENT_A_FINAL_AUDIT_R14','overall',status(passed),'algorithmVersion','Stage55-A-causal-dual-hypothesis-v11','algorithmSignature','c467ac3dee4f816aafc56b59d37030631e4be5b22eecc7d4f11d88f0a66cd8c9','actualPairedPackets',total,'plannedPairedPackets',400000,'bootstrapDrawsPerPoint',10000,'stageBetterPoints',better,'formalPoints',20,'ciCrossZeroPoints',inconclusive,'case2Minus30Conclusion','statistically-inconclusive; retained without claiming superiority','rawToReportRecalculation',status(ok),'sourceBoundary',status(source.passed),'userAcceptanceHash',v4Sha256(acceptance),'cellHashes',hashes,'experimentConditionsChanged',false,'paperCodeChanged',false,'admission',ternary(passed,'ADMIT_EXPERIMENT_B','DO_NOT_ADMIT_EXPERIMENT_B'));
out=fullfile(root,'results','reports');write(fullfile(out,'EXPERIMENT_A_FINAL_AUDIT_R14.json'),jsonencode(audit,'PrettyPrint',true));write(fullfile(out,'EXPERIMENT_A_FINAL_AUDIT_R14.md'),sprintf('# Experiment A final audit - R14\n\nOverall: `%s`; admission: `%s`.\n\n400000/400000 paired packets and 10000 bootstrap draws per point were verified. Stage55 was lower at 19/20 points; Case 2/-30 dB remains statistically inconclusive and is not described as superior. Conditions and Paper were unchanged.\n',audit.overall,audit.admission));if ~passed,error('V4:R14FinalAudit','R14 final audit failed.');end
end
function x=status(ok),if ok,x='PASS';else,x='FAIL';end,end
function x=ternary(ok,a,b),if ok,x=a;else,x=b;end,end
function write(path,text),f=fopen(path,'w','n','UTF-8');cl=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear cl,end
